// DeployServiceHandler is an implementation of the controlplane.v1.DeployService service.
type DeployServiceHandler interface {
	// GetTenant returns the caller's deploy-product enrollment, or NotFound if
	// the organization has never deployed. The /deploy empty state reads this.
	GetTenant(context.Context, *connect.Request[v1.GetDeployTenantRequest]) (*connect.Response[v1.GetDeployTenantResponse], error)
	// CreateTenant enrolls the caller's organization, allocating its immutable
	// hostname slug. Idempotent: a second call returns the existing tenant
	// rather than failing, because the /deploy onboarding path can be entered
	// twice and a duplicate-enrollment error is not a thing a user can act on.
	CreateTenant(context.Context, *connect.Request[v1.CreateDeployTenantRequest]) (*connect.Response[v1.CreateDeployTenantResponse], error)
	CreateEnvironment(context.Context, *connect.Request[v1.CreateDeployEnvironmentRequest]) (*connect.Response[v1.CreateDeployEnvironmentResponse], error)
	GetEnvironment(context.Context, *connect.Request[v1.GetDeployEnvironmentRequest]) (*connect.Response[v1.GetDeployEnvironmentResponse], error)
	ListEnvironments(context.Context, *connect.Request[v1.ListDeployEnvironmentsRequest]) (*connect.Response[v1.ListDeployEnvironmentsResponse], error)
	UpdateEnvironment(context.Context, *connect.Request[v1.UpdateDeployEnvironmentRequest]) (*connect.Response[v1.UpdateDeployEnvironmentResponse], error)
	// DeleteEnvironment tears down the environment and its namespace. Refuses
	// with FailedPrecondition while the environment still has deployments,
	// unless force is set — deleting a namespace out from under running
	// workloads is the kind of thing a user should have to say twice.
	DeleteEnvironment(context.Context, *connect.Request[v1.DeleteDeployEnvironmentRequest]) (*connect.Response[v1.DeleteDeployEnvironmentResponse], error)
	// EnsureEnvironment makes an environment with this NAME exist in the
	// caller's org and returns it: created when absent, returned unchanged when
	// present. It is what `forge env deploy` calls for an env that declares
	// forge.ControlPlane, so a hosted environment is DECLARED in the project's
	// KCL rather than provisioned by a manual CreateEnvironment step.
	//
	// WHY A SEPARATE RPC RATHER THAN AN IDEMPOTENT CreateEnvironment. The two
	// callers want different answers to "that name is taken". A human creating
	// an environment who collides with an existing name has made a mistake and
	// must be told (AlreadyExists); a declarative client re-running an
	// unchanged project has made no mistake and must converge. Folding both
	// into Create would make the human's collision silent or the re-run an
	// error, and a request flag choosing between them is two RPCs sharing one
	// name. `created` reports which happened so a caller can still tell.
	//
	// An existing environment whose IMMUTABLE fields (kind, tenant cluster)
	// differ from the spec is FailedPrecondition, never silently kept or
	// rewritten: a declaration that disagrees with a namespace that already
	// exists has no correct reading.
	EnsureEnvironment(context.Context, *connect.Request[v1.EnsureDeployEnvironmentRequest]) (*connect.Response[v1.EnsureDeployEnvironmentResponse], error)
	CreateDeployment(context.Context, *connect.Request[v1.CreateDeploymentRequest]) (*connect.Response[v1.CreateDeploymentResponse], error)
	GetDeployment(context.Context, *connect.Request[v1.GetDeploymentRequest]) (*connect.Response[v1.GetDeploymentResponse], error)
	ListDeployments(context.Context, *connect.Request[v1.ListDeploymentsRequest]) (*connect.Response[v1.ListDeploymentsResponse], error)
	// UpdateDeployment replaces the DECLARED state. Reserved capacity changes
	// here rather than through Scale, because changing what a replica reserves
	// changes the bill in a way that adding replicas at a known size does not.
	UpdateDeployment(context.Context, *connect.Request[v1.UpdateDeploymentRequest]) (*connect.Response[v1.UpdateDeploymentResponse], error)
	DeleteDeployment(context.Context, *connect.Request[v1.DeleteDeploymentRequest]) (*connect.Response[v1.DeleteDeploymentResponse], error)
	// EnsureDeployment makes a deployment with this NAME in this environment
	// hold exactly this tier spec: created when absent, its spec replaced when
	// it differs, untouched when identical. The declarative twin of
	// CreateDeployment + UpdateDeployment, for EnsureEnvironment's reason: a
	// forge deploy is "make it so", and its next step is
	// PublishDeploymentConfig on the returned id.
	//
	// It runs every gate Create and Update run: entitlement, role, strict spec
	// decode, forge's Validate, the hosted shape band, and capacity admission.
	// A different TIER on an existing name is FailedPrecondition (a tier change
	// is a delete and a create; see UpdateDeploymentRequest).
	EnsureDeployment(context.Context, *connect.Request[v1.EnsureDeploymentRequest]) (*connect.Response[v1.EnsureDeploymentResponse], error)
	// Promote re-points an environment at an ALREADY-BUILT release.
	//
	// It NEVER builds. See PromoteReleaseRequest: there is no image field, no
	// build input, and no way to express one, so "the bytes that passed staging
	// are the bytes that reach prod" holds by construction rather than by
	// policy. A version that was never cut fails with FailedPrecondition; there
	// is no path that responds by building it.
	Promote(context.Context, *connect.Request[v1.PromoteReleaseRequest]) (*connect.Response[v1.PromoteReleaseResponse], error)
	// Rollback re-points an environment at an OLDER release. Mechanically
	// identical to Promote — the same digest re-point, reusing images already
	// in the registry — and separate only so intent is recorded: a rollback
	// must read as a rollback in the audit trail.
	//
	// Having its own RPC rather than a `kind` field on Promote is what keeps
	// the kind honest. A client cannot mislabel a promotion as a rollback,
	// because a client never states the kind at all; the server records which
	// method was called.
	Rollback(context.Context, *connect.Request[v1.RollbackReleaseRequest]) (*connect.Response[v1.RollbackReleaseResponse], error)
	// Scale changes the RUN STATE (running / suspended) and nothing else.
	// Narrow on purpose: this is the button on a detail page, and a request
	// shape that could also change reserved capacity would let a mis-wired
	// control change the bill. forge's tiers carry no replica count, so there
	// is no count to scale; suspending is the one thing left.
	//
	// A suspend is the tenant's own. It is NOT the same as the environment's
	// automatic scale-to-zero, and neither one stops storage.
	Scale(context.Context, *connect.Request[v1.ScaleDeploymentRequest]) (*connect.Response[v1.ScaleDeploymentResponse], error)
	// GetStatus returns the deployment with BOTH halves — declared and
	// observed — plus the derived drift the UI badges. The 15s poll on the
	// /deploy detail page calls this.
	GetStatus(context.Context, *connect.Request[v1.GetDeploymentStatusRequest]) (*connect.Response[v1.GetDeploymentStatusResponse], error)
	// StreamLogs streams build or runtime output for one deployment.
	//
	// SNAPSHOT-THEN-TAIL, with a resume cursor. The first response carries the
	// buffered backlog and the sequence it ends at; subsequent responses carry
	// new lines. A client that drops the connection reconnects with
	// after_sequence and receives only what it missed — which is what makes a
	// transient disconnect a gap of milliseconds instead of a re-read of the
	// whole buffer.
	StreamLogs(context.Context, *connect.Request[v1.StreamDeploymentLogsRequest], *connect.ServerStream[v1.StreamDeploymentLogsResponse]) error
	// PublishDeploymentConfig packages one deployment as a config artifact and
	// publishes it to the tenant's config subtree in the platform registry.
	//
	// THE ARTIFACT HOLDS EXACTLY ONE forge.dev/v1alpha1 CR (a SimpleBackend,
	// StaticSite or ManagedDatabase) whose spec IS the stored forge tier spec.
	// Identity (org, environment, deployment) is carried in the CR's forge.dev/*
	// LABELS, never in the spec. Flux applies that CR and nothing else; the
	// tier operator renders the workload from it, so Flux never owns a
	// rendered Deployment or Service.
	//
	// THIS IS THE ONLY PATH TO PRODUCTION, and the request shape is what makes
	// that true rather than this server's good behaviour. The request carries a
	// deployment id and NOTHING ELSE — no image, no manifest, no namespace, no
	// cluster, no registry path. Every one of those is derived server-side from
	// the deployment's own row and the platform's own configuration, so there is
	// no field in which a caller could name bytes to publish or a place to
	// publish them. An RPC that accepted a loose image reference would be a
	// second path to production and would void the promotion guarantee; this one
	// cannot become that by accident, because there is nothing to populate.
	//
	// IT PUBLISHES, IT DOES NOT APPLY. The artifact reaches the registry and the
	// response reports the digest it landed at. Reconciliation — the Flux
	// objects that pull that digest and apply it to the destination cluster — is
	// a separate step performed by the platform, so a successful response means
	// "these bytes exist at this address", never "this is running".
	//
	// IDEMPOTENT BY CONTENT ADDRESS rather than by a key. The render is
	// reproducible, so re-publishing an unchanged deployment produces the same
	// bytes, the same digest and the same reference — a repeat call overwrites
	// an object with itself. It is marked idempotent for that reason and not
	// because the server de-duplicates anything.
	PublishDeploymentConfig(context.Context, *connect.Request[v1.PublishDeploymentConfigRequest]) (*connect.Response[v1.PublishDeploymentConfigResponse], error)
	// CutRelease records a version label over a set of artifacts that were
	// ALREADY BUILT AND PUSHED. It is the other half of Promote: Promote can
	// only re-point at a release, and until this RPC existed there was no way
	// to create one over the wire, so the push-to-deploy path stopped at the
	// registry.
	//
	// IT BUILDS NOTHING EITHER. A caller states digests it has in hand; this
	// server never produces bytes. The natural place for that caller is CI,
	// immediately after `docker/build-push-action` reports the digest it just
	// pushed — which is why the request carries digests and not a Dockerfile.
	//
	// IDEMPOTENT ON (caller's org, version), which is not a check this handler
	// performs but the unique index the ledger already carries. CI retries, and
	// a re-run on the same commit must not cut a second release. Re-cutting the
	// SAME version with the SAME artifacts returns the release that already
	// exists with created=false; re-cutting it with DIFFERENT artifacts is
	// AlreadyExists, because a version label that meant two different digest
	// sets would void every guarantee Promote rests on.
	CutRelease(context.Context, *connect.Request[v1.CutReleaseRequest]) (*connect.Response[v1.CutReleaseResponse], error)
	// ListReleases feeds the promote picker. Releases are immutable, so there
	// is deliberately no UpdateRelease anywhere in this service — a correction
	// is a new release.
	ListReleases(context.Context, *connect.Request[v1.ListDeployReleasesRequest]) (*connect.Response[v1.ListDeployReleasesResponse], error)
	GetRelease(context.Context, *connect.Request[v1.GetDeployReleaseRequest]) (*connect.Response[v1.GetDeployReleaseResponse], error)
	// ListPromotions returns an environment's ledger, newest first — the
	// timeline the UI renders and the rollback picker reads. Append-only, so
	// this is the COMPLETE record, including what was rolled back FROM, which a
	// current-pointer read cannot show.
	ListPromotions(context.Context, *connect.Request[v1.ListDeployPromotionsRequest]) (*connect.Response[v1.ListDeployPromotionsResponse], error)
	// ListUsage returns metered infrastructure usage for the caller's org, with
	// per-resource attribution. Post-hoc: these rows come from a sweeper that
	// read the live cluster, so a deployment declared and never applied appears
	// in none of them.
	ListUsage(context.Context, *connect.Request[v1.ListDeployUsageRequest]) (*connect.Response[v1.ListDeployUsageResponse], error)
}

